let lang=localStorage.getItem('bb-lang')==='es'?'es':'en';
let state={text:'',selectedNeeds:new Set(),profile:{zip:'',household_size:null,children_count:null,child_under_5:null,income_range:null,situations:[],needs:[],urgency:null,language:lang},steps:[],stepIndex:0,prefilled:false,crisis:false,plan:null,filter:'all',adminToken:sessionStorage.getItem('bb-admin')||'',adminResources:[],analytics:null,adminSearch:'',adminCategory:'all'};
const t=k=>copy[lang][k]||k;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){toastEl.textContent=message;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),3500)}
async function setLanguage(next){lang=next;localStorage.setItem('bb-lang',lang);document.documentElement.lang=lang;state.profile.language=lang;document.querySelector('#language').textContent=lang==='en'?'Español':'English';document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));document.querySelector('#crisis-footer').innerHTML=t('crisisFooter');if(state.plan){try{state.plan=await api(`/api/plans/${state.plan.id}?lang=${lang}`)}catch{}}renderRoute()}
function go(url){history.pushState({},'',url);renderRoute();window.scrollTo(0,0);main.focus({preventScroll:true})}
document.querySelector('#language').addEventListener('click',()=>setLanguage(lang==='en'?'es':'en'));
document.addEventListener('click',e=>{const a=e.target.closest('a[data-link]');if(a){e.preventDefault();go(a.getAttribute('href'))}});
window.addEventListener('popstate',renderRoute);
function crisisPanel(){return `<section class="crisis" role="alert"><h2>${t('crisisTitle')}</h2><p>${t('crisisBody')}</p><p><a href="tel:911">911</a> · <a href="tel:988">988</a> · <a href="tel:18007997233">800-799-7233</a> · <a href="tel:211">211</a></p></section>`}
function categoryButtons(selected,attribute='data-category'){return categoryKeys.map(k=>`<button class="category" type="button" ${attribute}="${k}" aria-pressed="${selected.includes(k)}"><span class="category-icon" aria-hidden="true">${categoryIcons[k]}</span><span>${t(k)}</span>${selected.includes(k)?'<span class="category-check" aria-hidden="true">✓</span>':''}</button>`).join('')}
function renderHome(){
  main.innerHTML=`<div class="shell"><div class="hero"><div><p class="eyebrow">${t('eyebrow')}</p><h1>${t('hero')}</h1><p class="intro">${t('intro')}</p><div class="entry-card"><label class="field-label" for="situation">${t('describe')}</label><textarea id="situation" maxlength="3000" placeholder="${esc(t('placeholder'))}">${esc(state.text)}</textarea><div class="form-actions"><button class="btn btn-amber" id="build" type="button">${t('build')} <span aria-hidden="true">→</span></button><button class="text-link" id="demo" type="button">${t('example')}</button></div><p class="form-error" id="home-error" hidden></p></div></div><aside class="hero-side"><div class="note"><div class="note-icon" aria-hidden="true">✳</div><h2>${t('noteTitle')}</h2><p>${t('noteBody')}</p></div><div class="trust-row"><div><strong>✓</strong>${t('trust1')}</div><div><strong>◇</strong>${t('trust2')}</div><div><strong>▣</strong>${t('trust3')}</div></div></aside></div><div class="section-head"><h2>${t('orChoose')}</h2></div><div class="category-grid">${categoryButtons([...state.selectedNeeds])}</div><div class="category-action"><button class="btn btn-primary" id="category-continue" ${state.selectedNeeds.size?'':'disabled'}>${t('continue')} <span aria-hidden="true">→</span></button></div></div>`;
  main.querySelector('#situation').addEventListener('input',e=>state.text=e.target.value);
  main.querySelector('#build').addEventListener('click',startFromText);
  main.querySelector('#demo').addEventListener('click',demo);
  main.querySelector('#category-continue').addEventListener('click',()=>{state.profile.needs=[...state.selectedNeeds];prepareWizard(false)});
  main.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{state.selectedNeeds.has(b.dataset.category)?state.selectedNeeds.delete(b.dataset.category):state.selectedNeeds.add(b.dataset.category);renderHome()}));
}
async function api(url,options={}){const r=await fetch(url,{headers:{'content-type':'application/json',...(options.headers||{})},...options});let body;try{body=await r.json()}catch{body={error:t('error')}}if(!r.ok)throw new Error(body.error||t('error'));return body}
async function startFromText(){
  if(!state.text.trim()&&!state.selectedNeeds.size){const el=main.querySelector('#home-error');el.hidden=false;el.textContent=t('emptyText');return}
  if(!state.text.trim()){state.profile.needs=[...state.selectedNeeds];return prepareWizard(false)}
  state.crisis=/suicid|kill myself|self.harm|hurt myself|domestic violence|abuse|being hurt|immediate danger|me quiero morir|violencia doméstica|maltrato|peligro inmediato/i.test(state.text);
  main.innerHTML=`<div class="shell steps-layout">${state.crisis?crisisPanel():''}<div class="loading" role="status"><p>${t('loading')}</p><div class="skeleton"></div><div class="skeleton"></div></div></div>`;
  try{const extracted=await api('/api/extract',{method:'POST',body:JSON.stringify({text:state.text})});state.crisis=!!extracted.crisis_flag;state.profile={...state.profile,...Object.fromEntries(Object.entries(extracted).filter(([k])=>['zip','household_size','children_count','child_under_5','income_range','situations','needs','urgency'].includes(k)))};state.profile.zip ||= '';
    state.profile.needs=[...new Set([...(state.profile.needs||[]),...state.selectedNeeds])];state.profile.crisis_flag=state.crisis;state.prefilled=true;
    if(extracted.detected_language==='es'&&lang==='en')setLanguage('es');
    prepareWizard(true);if(extracted.warning)toast(extracted.warning);
  }catch(e){state.profile.needs=[...state.selectedNeeds];prepareWizard(false);toast(e.message)}
}
function demo(){
  state.text="I'm a single mom with 2 kids, ages 3 and 8. I just lost my job last week. We live in 78741 and I'm behind on the electric bill and running low on groceries.";
  state.profile={zip:'78741',household_size:3,children_count:2,child_under_5:true,income_range:null,situations:['single_parent','lost_job'],needs:['food','utilities','school_childcare','healthcare','employment'],urgency:'today',language:lang};
  state.prefilled=true;state.crisis=false;createPlan();
}
function missingStep(key){const p=state.profile; if(key==='zip')return !p.zip;if(key==='household_size')return p.household_size==null;if(key==='children_count')return p.children_count==null;if(key==='income_range')return p.income_range==null;if(key==='situations')return !p.situations?.length;if(key==='needs')return !p.needs?.length;if(key==='urgency')return !p.urgency;return true}
function prepareWizard(fromText){state.steps=['zip','household_size','children_count','income_range','situations','needs','urgency'].filter(k=>!fromText||missingStep(k));state.steps.push('review');state.stepIndex=0;go('/questions')}
const stepTitle={zip:'zipQ',household_size:'householdQ',children_count:'childrenQ',income_range:'incomeQ',situations:'situationsQ',needs:'needsQ',urgency:'urgencyQ',review:'reviewQ'};
const stepHint={zip:'zipHint',household_size:'householdHint',children_count:'childrenHint',income_range:'incomeHint',situations:'situationsHint',needs:'needsHint',urgency:'urgencyHint',review:'reviewHint'};
function questionContent(key){const p=state.profile;
  if(key==='zip')return `<label class="field-label" for="zip-input">${t('zipQ')}</label><input class="input-lg" id="zip-input" inputmode="numeric" autocomplete="postal-code" maxlength="5" pattern="[0-9]{5}" value="${esc(p.zip)}"><p class="form-error" id="step-error" hidden></p>`;
  if(key==='household_size')return `<div class="stepper"><button type="button" data-count="-1" aria-label="Decrease household size">−</button><strong id="count-value">${p.household_size??1}</strong><button type="button" data-count="1" aria-label="Increase household size">+</button></div>`;
  if(key==='children_count')return `<div class="stepper"><button type="button" data-count="-1" aria-label="Decrease number of children">−</button><strong id="count-value">${p.children_count??0}</strong><button type="button" data-count="1" aria-label="Increase number of children">+</button></div><p class="field-label" style="margin-top:24px">${t('under5')}</p><div class="choice-list"><label class="choice"><input type="radio" name="under5" value="yes" ${p.child_under_5===true?'checked':''}>${t('yes')}</label><label class="choice"><input type="radio" name="under5" value="no" ${p.child_under_5===false?'checked':''}>${t('no')}</label></div>`;
  if(key==='income_range')return `<div class="choice-list">${incomeKeys.map(k=>`<label class="choice"><input type="radio" name="income" value="${k}" ${p.income_range===k?'checked':''}>${t(k==='under_1000'?'under_1000':k)}</label>`).join('')}</div>`;
  if(key==='situations')return `<div class="choices-grid">${situationKeys.map(k=>`<label class="choice"><input type="checkbox" name="situation" value="${k}" ${(p.situations||[]).includes(k)?'checked':''}>${t(k)}</label>`).join('')}</div>`;
  if(key==='needs')return `<div class="category-grid">${categoryButtons(p.needs||[],'data-wizard-category')}</div><p class="form-error" id="step-error" hidden></p>`;
  if(key==='urgency')return `<div class="choice-list">${[['today','todayUrgent'],['week','weekUrgent'],['month','monthUrgent']].map(([v,k])=>`<label class="choice"><input type="radio" name="urgency" value="${v}" ${p.urgency===v?'checked':''}>${t(k)}</label>`).join('')}</div>`;
  return `<div class="admin-grid">${[['zip',p.zip||t('notSure')],['household_size',p.household_size??t('notSure')],['children_count',p.children_count??t('notSure')],['income_range',p.income_range?t(p.income_range):t('notSure')],['situations',(p.situations||[]).map(t).join(', ')||t('none')],['needs',(p.needs||[]).map(t).join(', ')||t('none')],['urgency',p.urgency?t(p.urgency==='today'?'todayUrgent':p.urgency==='week'?'weekUrgent':'monthUrgent'):t('notSure')]].map(([k,v])=>`<div class="choice"><span style="flex:1"><strong>${esc(k==='zip'?'ZIP':t(stepTitle[k]).replace(/[?¿]/g,''))}</strong><br>${esc(v)}</span><button class="text-link" type="button" data-edit="${k}">${t('edit')}</button></div>`).join('')}</div>`;
}
function renderWizard(){const key=state.steps[state.stepIndex]||'review';const total=state.steps.length;
  main.innerHTML=`<div class="shell steps-layout"><div class="step-top"><span>${t('step')} ${state.stepIndex+1} ${t('of')} ${total}</span><span>${Math.round((state.stepIndex+1)/total*100)}%</span></div><div class="progress" role="progressbar" aria-valuenow="${state.stepIndex+1}" aria-valuemin="0" aria-valuemax="${total}" aria-label="Progress"><span style="width:${(state.stepIndex+1)/total*100}%"></span></div>${state.crisis?crisisPanel():''}${state.prefilled?`<div class="notice">${t('prefilled')}</div>`:''}<div class="panel step-card"><h1>${t(stepTitle[key])}</h1><p class="hint">${t(stepHint[key])}</p>${questionContent(key)}<div class="step-controls"><button type="button" class="btn btn-outline" id="back">${t('back')}</button><div class="page-actions">${key!=='zip'&&key!=='review'?`<button type="button" class="btn btn-text" id="skip">${t('skip')}</button>`:''}<button type="button" class="btn btn-primary" id="next">${key==='review'?t('showPlan'):t('next')} <span aria-hidden="true">→</span></button></div></div></div></div>`;
  main.querySelector('#back').addEventListener('click',()=>state.stepIndex? (state.stepIndex--,renderWizard()):go('/'));
  main.querySelector('#next').addEventListener('click',()=>advanceWizard(false));
  main.querySelector('#skip')?.addEventListener('click',()=>advanceWizard(true));
  main.querySelectorAll('[data-count]').forEach(b=>b.addEventListener('click',()=>{let field=key==='household_size'?'household_size':'children_count';let current=state.profile[field]??(field==='household_size'?1:0);state.profile[field]=Math.min(10,Math.max(field==='household_size'?1:0,current+Number(b.dataset.count)));main.querySelector('#count-value').textContent=state.profile[field]}));
  main.querySelectorAll('[data-wizard-category]').forEach(b=>b.addEventListener('click',()=>{const selected=new Set(state.profile.needs||[]);selected.has(b.dataset.wizardCategory)?selected.delete(b.dataset.wizardCategory):selected.add(b.dataset.wizardCategory);state.profile.needs=[...selected];renderWizard()}));
  main.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>{if(!state.steps.includes(b.dataset.edit))state.steps.splice(state.steps.length-1,0,b.dataset.edit);state.stepIndex=state.steps.indexOf(b.dataset.edit);renderWizard()}));
}
function advanceWizard(skip){const key=state.steps[state.stepIndex];const p=state.profile;
  if(!skip){
    if(key==='zip'){p.zip=main.querySelector('#zip-input').value.trim();if(!/^\d{5}$/.test(p.zip)){const el=main.querySelector('#step-error');el.hidden=false;el.textContent=t('invalidZip');return}}
    if(key==='household_size')p.household_size??=1;
    if(key==='children_count'){p.children_count??=0;const checked=main.querySelector('input[name=under5]:checked');p.child_under_5=checked?checked.value==='yes':null}
    if(key==='income_range')p.income_range=main.querySelector('input[name=income]:checked')?.value||null;
    if(key==='situations')p.situations=[...main.querySelectorAll('input[name=situation]:checked')].map(x=>x.value);
    if(key==='urgency')p.urgency=main.querySelector('input[name=urgency]:checked')?.value||null;
    if(key==='review'){if(!/^\d{5}$/.test(p.zip)){state.steps.splice(state.steps.length-1,0,'zip');state.stepIndex=state.steps.indexOf('zip');renderWizard();return}if(!p.needs.length){state.steps.splice(state.steps.length-1,0,'needs');state.stepIndex=state.steps.indexOf('needs');renderWizard();return}createPlan();return}
  }
  state.stepIndex=Math.min(state.steps.length-1,state.stepIndex+1);renderWizard();
}
async function createPlan(){main.innerHTML=`<div class="shell steps-layout">${state.crisis?crisisPanel():''}<div class="loading" role="status"><p>${t('loading')}</p><div class="skeleton"></div><div class="skeleton"></div></div></div>`;
  try{state.profile.language=lang;state.profile.crisis_flag=state.crisis;state.plan=await api('/api/plans',{method:'POST',body:JSON.stringify(state.profile)});state.filter='all';go(`/plan/${state.plan.id}/resources`);if(state.plan.ai_pending)pollPlan(state.plan.id)}catch(e){toast(e.message);if(state.steps.length)renderWizard();else renderHome()}}
async function pollPlan(id){for(let i=0;i<4;i++){await new Promise(r=>setTimeout(r,2800));if(state.plan?.id!==id)return;try{const fresh=await api(`/api/plans/${id}`);if(JSON.stringify(fresh.action_plan)!==JSON.stringify(state.plan.action_plan)){state.plan={...state.plan,...fresh};if(location.pathname===`/plan/${id}`)renderActionPlan();return}}catch{return}}}
const docLabel=s=>docs[s]?.[lang==='es'?1:0]||s;
const safeLink=url=>{try{const u=new URL(url);return u.protocol==='https:'?u.href:''}catch{return ''}};
function resourceCard(r){const es=lang==='es',url=safeLink(r.apply_url),source=safeLink(r.source_url),selected=state.plan.selected_ids.includes(r.id),done=state.plan.done_ids.includes(r.id);
  return `<article class="program" id="resource-${esc(r.id)}"><div class="program-top"><div><h3>${esc(r.name)}</h3><p class="organization">${esc(r.organization)}</p></div><span class="strength ${esc(r.strength||'worth_checking')}">${t(r.strength||'worth_checking')}</span></div><p class="why"><strong>${t('why')}:</strong> ${esc(es?r.why_es:r.why_en)}</p><div class="program-body"><div><h4>${t('what')}</h4><p>${esc(es?r.description_es:r.description_en)}</p></div><div><h4>${t('who')}</h4><p>${esc(es?r.eligibility_summary_es:r.eligibility_summary_en)}</p></div><div><h4>${t('bring')}</h4><div class="doc-chips">${r.documents_needed?.length?r.documents_needed.map(d=>`<span class="doc-chip">${esc(docLabel(d))}</span>`).join(''):`<span>${t('notSure')}</span>`}</div></div><div><h4>${t('how')}</h4><p>${esc(r.how_to_apply|| (es?'Use el enlace oficial o llame para preguntar.':'Use the official link or call to ask.'))}</p></div></div><div class="contact-row">${r.phone?`<a href="tel:${esc(r.phone.replace(/[^+\d]/g,''))}">${t('call')} ${esc(r.phone)}</a>`:''}${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${t('website')} ↗</a>`:''}${r.address?`<a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(r.address)}" target="_blank" rel="noopener noreferrer">${t('maps')} ↗</a>`:''}${r.hours?`<span>${t('hours')}: ${esc(r.hours)}</span>`:''}</div><div class="program-actions"><button class="btn btn-outline" data-explain="${esc(r.id)}">${t('explain')}</button><button class="btn btn-outline" data-select="${esc(r.id)}" aria-pressed="${selected}">${selected?'✓ '+t('added'):'+ '+t('add')}</button><button class="btn btn-outline" data-done="${esc(r.id)}" aria-pressed="${done}">${done?'✓ '+t('doneMarked'):t('done')}</button></div><div id="explain-${esc(r.id)}" aria-live="polite"></div><div class="program-meta"><span>${t('lastVerified')}: ${esc(r.last_verified_date||'—')}</span>${source?`<a href="${esc(source)}" target="_blank" rel="noopener noreferrer">${t('source')} ↗</a>`:''}<button class="text-link" data-feedback="${esc(r.id)}:helpful">${t('helpful')}</button><button class="text-link" data-feedback="${esc(r.id)}:not_helpful">${t('notHelpful')}</button></div></article>`;
}
function renderResults(){const p=state.plan;if(!p)return renderHome();const needs=p.profile.needs||[];const filtered=p.matched_resources.filter(r=>state.filter==='all'||(categoryKeys.includes(state.filter)?r.categories.includes(state.filter):state.filter==='online'?!!r.apply_url:state.filter==='walkin'?!!r.address:r.hours==='24/7'));
  const grouped=new Map();for(const r of filtered){const group=needs.find(k=>r.categories.includes(k))||r.categories[0];if(!grouped.has(group))grouped.set(group,[]);grouped.get(group).push(r)}
  main.innerHTML=`<div class="shell"><div class="page-head"><div><p class="eyebrow">${t('summary')}: ${p.profile.household_size?t('household')+' '+p.profile.household_size+', ':''}${needs.map(t).join(', ')}, ${t('zip')} ${esc(p.profile.zip)}</p><h1>${t('results')}</h1><p class="summary">${t('matches')}</p></div><div class="page-actions"><button class="btn btn-outline" id="restart">${t('startOver')}</button></div></div>${state.crisis?crisisPanel():''}${p.out_of_coverage?`<div class="notice">${t('coverage')}</div>`:''}<div class="filters" aria-label="Resource filters">${[['all',t('all')],...needs.map(k=>[k,t(k)]),['open',t('openNow')],['online',t('applyOnline')],['walkin',t('walkIn')]].map(([k,label])=>`<button type="button" class="chip-button" data-filter="${k}" aria-pressed="${state.filter===k}">${label}</button>`).join('')}</div><div class="result-layout"><div>${filtered.length?[...grouped].map(([k,list])=>`<section class="results-group"><h2>${t(k)}</h2>${list.map(resourceCard).join('')}</section>`).join(''):`<div class="empty"><h3>${t(p.matched_resources.length?'resultsEmpty':'noMatches')}</h3><a href="tel:211">${t('fallback')}</a></div>`}<p class="disclaimer">${t('disclaimer')}</p></div><aside class="panel side-panel"><h2>${t('plan')}</h2><p>${p.selected_ids.length} ${t('selected')}. ${t('selectedInfo')}</p><button class="btn btn-amber" id="view-plan">${t('viewPlan')} →</button><h2>${t('fallback')}</h2><p>${t('fallbackText')}</p><a class="btn btn-outline" href="tel:211">${t('call')} 211</a></aside></div></div>`;
  main.querySelector('#restart').addEventListener('click',reset);
  main.querySelector('#view-plan').addEventListener('click',()=>go(`/plan/${p.id}`));
  main.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;renderResults()}));
  main.querySelectorAll('[data-select]').forEach(b=>b.addEventListener('click',()=>updatePlan({selected_ids:p.selected_ids.includes(b.dataset.select)?p.selected_ids.filter(x=>x!==b.dataset.select):[...p.selected_ids,b.dataset.select]},renderResults)));
  main.querySelectorAll('[data-done]').forEach(b=>b.addEventListener('click',()=>updatePlan({done_ids:p.done_ids.includes(b.dataset.done)?p.done_ids.filter(x=>x!==b.dataset.done):[...p.done_ids,b.dataset.done]},renderResults)));
  main.querySelectorAll('[data-explain]').forEach(b=>b.addEventListener('click',async()=>{const target=main.querySelector(`#explain-${CSS.escape(b.dataset.explain)}`);target.innerHTML=`<p class="hint">${t('loadingPlan')}</p>`;try{const answer=await api('/api/explain',{method:'POST',body:JSON.stringify({resource_id:b.dataset.explain,language:lang})});target.innerHTML=`<ul class="simple-list">${answer.bullets.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`}catch(e){target.textContent=e.message}}));
  main.querySelectorAll('[data-feedback]').forEach(b=>b.addEventListener('click',async()=>{const [rid,rating]=b.dataset.feedback.split(':');try{await api('/api/feedback',{method:'POST',body:JSON.stringify({plan_id:p.id,resource_id:rid,rating})});toast(t('thanks'))}catch(e){toast(e.message)}}));
}
async function updatePlan(patch,after){try{state.plan=await api(`/api/plans/${state.plan.id}`,{method:'PATCH',body:JSON.stringify(patch)});if(state.plan.profile.language!==lang)state.plan=await api(`/api/plans/${state.plan.id}?lang=${lang}`);after()}catch(e){toast(e.message)}}
function timelineSteps(items){const visible=items.filter(x=>!x.resource_id||state.plan.selected_ids.includes(x.resource_id));return visible.length?visible.map(x=>`<div class="timeline-card"><p>${esc(x.action)}</p><p class="why-text">${esc(x.why)}</p>${x.resource_id?`<a href="/plan/${state.plan.id}/resources#resource-${esc(x.resource_id)}" data-link>${t('resources')} ↗</a>`:''}</div>`).join(''):`<div class="timeline-card"><p>${t('noData')}</p></div>`}
function renderActionPlan(){const p=state.plan;if(!p)return renderHome();const plan=p.action_plan;const share=location.origin+`/plan/${p.id}`;
  main.innerHTML=`<div class="shell timeline"><div class="page-head"><div><p class="eyebrow">${t('zip')} ${esc(p.profile.zip)}</p><h1>${t('plan')}</h1><p class="summary">${t('matches')}</p></div><div class="page-actions"><button class="btn btn-outline" id="resource-link">${t('resources')}</button><button class="btn btn-outline" id="restart">${t('startOver')}</button></div></div>${state.crisis?crisisPanel():''}<div class="timeline-section"><h2>${t('today')}</h2>${timelineSteps(plan.today)}</div><div class="timeline-section"><h2>${t('bringHeading')}</h2><div class="timeline-card">${plan.bring.length?plan.bring.map(d=>`<label class="check-item"><input type="checkbox" data-document="${esc(d)}" ${p.checklist_state[d]?'checked':''}><span>${esc(docLabel(d))}</span></label>`).join(''):`<p>${t('notSure')}</p>`}</div></div><div class="timeline-section"><h2>${t('thisWeek')}</h2>${timelineSteps(plan.this_week)}</div><div class="timeline-section"><h2>${t('ifNot')}</h2>${plan.fallbacks.map(f=>`<div class="timeline-card"><p><strong>${esc(f.if)}:</strong> ${esc(f.then)}</p></div>`).join('')}</div><p class="closing">${esc(plan.encouragement)}</p><div class="page-actions"><button class="btn btn-primary" id="print">${t('print')}</button><button class="btn btn-outline" id="speak">${t('read')}</button><button class="btn btn-outline" id="share-toggle">${t('share')}</button></div><div class="share-box" id="share-box" hidden><label for="share-url">${t('shareLink')}</label><input id="share-url" readonly value="${esc(share)}"><p class="hint">${t('shareInfo')}</p><div class="page-actions"><button class="btn btn-outline" id="copy-link">${t('copy')}</button><a class="btn btn-outline" href="mailto:?subject=${encodeURIComponent('BenefitBridge plan')}&body=${encodeURIComponent(share)}">${t('email')}</a><a class="btn btn-outline" href="sms:?body=${encodeURIComponent(share)}">${t('text')}</a></div></div><p class="disclaimer">${t('disclaimer')}</p></div>`;
  main.querySelector('#resource-link').addEventListener('click',()=>go(`/plan/${p.id}/resources`));main.querySelector('#restart').addEventListener('click',reset);
  main.querySelector('#print').addEventListener('click',()=>window.print());
  main.querySelector('#share-toggle').addEventListener('click',()=>{main.querySelector('#share-box').hidden=!main.querySelector('#share-box').hidden});
  main.querySelector('#copy-link').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(share);toast(t('copied'))}catch{main.querySelector('#share-url').select();document.execCommand('copy');toast(t('copied'))}});
  main.querySelector('#speak').addEventListener('click',e=>{if(!('speechSynthesis' in window))return toast(t('error'));if(speechSynthesis.speaking){speechSynthesis.cancel();e.currentTarget.textContent=t('read');return}const utterance=new SpeechSynthesisUtterance([t('plan'),...plan.today.map(x=>x.action),t('bringHeading'),...plan.bring.map(docLabel),...plan.this_week.map(x=>x.action),...plan.fallbacks.map(x=>x.then),plan.encouragement].join('. '));utterance.lang=lang==='es'?'es-US':'en-US';utterance.onend=()=>{const b=main.querySelector('#speak');if(b)b.textContent=t('read')};speechSynthesis.speak(utterance);e.currentTarget.textContent=t('stopRead')});
  main.querySelectorAll('[data-document]').forEach(b=>b.addEventListener('change',()=>updatePlan({checklist_state:{...p.checklist_state,[b.dataset.document]:b.checked}},renderActionPlan)));
}
function reset(){window.speechSynthesis?.cancel?.();state={...state,text:'',selectedNeeds:new Set(),profile:{zip:'',household_size:null,children_count:null,child_under_5:null,income_range:null,situations:[],needs:[],urgency:null,language:lang},steps:[],stepIndex:0,prefilled:false,crisis:false,plan:null,filter:'all'};go('/')}
function renderPlain(kind){const about=kind==='about';main.innerHTML=`<div class="shell plain-page"><p class="eyebrow">BenefitBridge</p><h1>${t(about?'aboutTitle':'privacyTitle')}</h1>${about?`<p>${t('about1')}</p><p>${t('about2')}</p><p>${t('about3')}</p><h2>${t('aboutSources')}</h2><p>${t('aboutSourcesText')}</p><h2>${t('aboutAI')}</h2><p>${t('aboutAIText')}</p>`:`<p>${t('privacy1')}</p><p>${t('privacy2')}</p><p>${t('privacy3')}</p><p>${t('privacy4')}</p>`}<a class="btn btn-primary" href="/" data-link>${t('startOver')}</a></div>`}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}const fields=rows.shift();return rows.filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(fields.map((f,i)=>{let v=r[i]||'';if(['categories','eligibility_rules','documents_needed','coverage_zip_codes'].includes(f)){try{v=JSON.parse(v)}catch{v=[]}}if(f==='is_active')v=v==='true';if(f==='priority_weight')v=Number(v);return[f,v]})))}
async function adminFetch(path,opts={}){return api(path,{...opts,headers:{...opts.headers,authorization:`Bearer ${state.adminToken}`}})}
async function loadAdmin(){try{const [a,b]=await Promise.all([adminFetch('/api/admin/resources'),adminFetch('/api/admin/analytics')]);state.adminResources=a.resources;state.analytics=b;renderAdmin()}catch(e){sessionStorage.removeItem('bb-admin');state.adminToken='';renderAdmin();toast(t('adminError'))}}
function adminForm(r={}){const field=(key,label,type='text')=>`<label>${label}${type==='textarea'?`<textarea name="${key}">${esc(r[key]||'')}</textarea>`:`<input name="${key}" type="${type}" value="${esc(r[key]||'')}">`}</label>`;
  return `<form id="resource-form" class="admin-card admin-grid"><input type="hidden" name="editing" value="${esc(r.id||'')}">${field('id','ID')}${field('name','Name')}${field('organization','Organization')}${field('categories','Categories (comma separated)')}${field('description_en','Description (English)','textarea')}${field('description_es','Descripción (español)','textarea')}${field('eligibility_summary_en','Who it is for (English)','textarea')}${field('eligibility_summary_es','Para quién es (español)','textarea')}${field('apply_url','Apply URL')}${field('source_url','Source URL')}${field('phone','Phone')}${field('address','Address')}${field('hours','Hours')}${field('documents_needed','Documents (comma separated)')}${field('coverage_state','State code')}${field('last_verified_date','Last verified','date')}<label>Coverage<select name="coverage_type">${['national','state','zip_list'].map(k=>`<option value="${k}" ${r.coverage_type===k?'selected':''}>${k}</option>`).join('')}</select></label>${field('coverage_zip_codes','ZIP codes (comma separated)')}<label>Priority weight<input name="priority_weight" type="number" value="${Number(r.priority_weight)||0}"></label><label class="choice"><input name="is_active" type="checkbox" ${r.is_active!==false?'checked':''}>Active</label><div><button class="btn btn-primary" type="submit">${t('saveResource')}</button></div></form>`}
function renderAdmin(){if(!state.adminToken){main.innerHTML=`<div class="shell plain-page"><h1>${t('adminTitle')}</h1><div class="panel step-card"><label class="field-label" for="admin-token">${t('adminSign')}</label><input id="admin-token" class="input-lg" type="password" autocomplete="off"><div class="form-actions"><button class="btn btn-primary" id="admin-login">${t('signIn')}</button></div></div></div>`;main.querySelector('#admin-login').addEventListener('click',()=>{state.adminToken=main.querySelector('#admin-token').value;sessionStorage.setItem('bb-admin',state.adminToken);loadAdmin()});return}
  const list=state.adminResources.filter(r=>(state.adminCategory==='all'||r.categories.includes(state.adminCategory))&&(`${r.name} ${r.organization}`.toLowerCase().includes(state.adminSearch.toLowerCase())));
  const metric=(title,entries,format)=>`<div><h3>${title}</h3>${entries?.length?`<ul>${entries.map(format).join('')}</ul>`:`<p>${t('noData')}</p>`}</div>`;
  main.innerHTML=`<div class="shell"><div class="page-head"><div><p class="eyebrow">BenefitBridge</p><h1>${t('dashboard')}</h1></div><button class="btn btn-outline" id="admin-logout">Log out</button></div><section class="admin-card"><h2>${t('analytics')}</h2><div class="admin-grid">${metric(t('plansDay'),state.analytics?.per_day,x=>`<li>${esc(x.day)}: ${x.count}</li>`)}${metric(t('topNeeds'),state.analytics?.top_needs,x=>`<li>${t(x[0])}: ${x[1]}</li>`)}${metric(t('topZips'),state.analytics?.top_zips,x=>`<li>${esc(x.zip)}: ${x.count}</li>`)}${metric(t('unhelpful'),state.analytics?.not_helpful,x=>`<li>${esc(x.resource_id)}: ${x.count}</li>`)}</div></section><section class="admin-card" style="margin-top:18px"><h2>${t('resourcesAdmin')}</h2><div class="admin-toolbar"><input id="admin-search" aria-label="${t('search')}" placeholder="${t('search')}" value="${esc(state.adminSearch)}"><select id="admin-category" aria-label="${t('categoryFilter')}"><option value="all">${t('allCategories')}</option>${categoryKeys.map(k=>`<option value="${k}" ${state.adminCategory===k?'selected':''}>${t(k)}</option>`).join('')}</select><button class="btn btn-outline" id="admin-add">${t('addResource')}</button><button class="btn btn-outline" id="admin-export">${t('export')}</button><label class="btn btn-outline" for="admin-import">${t('import')}</label><input id="admin-import" type="file" accept=".csv,text/csv" hidden></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Categories</th><th>${t('status')}</th><th>${t('lastVerified')}</th><th></th></tr></thead><tbody>${list.map(r=>{const stale=!r.last_verified_date||Date.now()-new Date(r.last_verified_date).getTime()>180*86400000;return`<tr><td><strong>${esc(r.name)}</strong><br>${esc(r.organization)}</td><td>${r.categories.map(t).join(', ')}</td><td>${r.is_active?'Active':'Inactive'}</td><td class="${stale?'stale':''}">${esc(r.last_verified_date||'—')} ${stale?' · '+t('needsVerify'):''}</td><td><button class="text-link" data-admin-edit="${esc(r.id)}">${t('edit')}</button><button class="text-link" data-admin-toggle="${esc(r.id)}">${r.is_active?t('deactivate'):t('reactivate')}</button></td></tr>`}).join('')}</tbody></table></div></section><div id="admin-editor" style="margin-top:18px"></div></div>`;
  main.querySelector('#admin-logout').addEventListener('click',()=>{state.adminToken='';sessionStorage.removeItem('bb-admin');renderAdmin()});
  main.querySelector('#admin-search').addEventListener('input',e=>{state.adminSearch=e.target.value;renderAdmin();main.querySelector('#admin-search').focus()});
  main.querySelector('#admin-category').addEventListener('change',e=>{state.adminCategory=e.target.value;renderAdmin()});
  main.querySelector('#admin-add').addEventListener('click',()=>openAdminEditor({}));
  main.querySelectorAll('[data-admin-edit]').forEach(b=>b.addEventListener('click',()=>openAdminEditor(state.adminResources.find(r=>r.id===b.dataset.adminEdit))));
  main.querySelectorAll('[data-admin-toggle]').forEach(b=>b.addEventListener('click',async()=>{const r=state.adminResources.find(x=>x.id===b.dataset.adminToggle);try{await adminFetch(`/api/admin/resources/${r.id}`,{method:'PUT',body:JSON.stringify({...r,is_active:!r.is_active})});await loadAdmin()}catch(e){toast(e.message)}}));
  main.querySelector('#admin-export').addEventListener('click',async()=>{const r=await fetch('/api/admin/export',{headers:{authorization:`Bearer ${state.adminToken}`}});if(!r.ok)return toast(t('adminError'));const blob=await r.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='benefitbridge-resources.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
  main.querySelector('#admin-import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const records=parseCSV(await file.text());await adminFetch('/api/admin/import',{method:'POST',body:JSON.stringify({resources:records})});toast(t('imported'));await loadAdmin()}catch(err){toast(err.message)}});
}
function openAdminEditor(r){const host=main.querySelector('#admin-editor');host.innerHTML=adminForm({...r,categories:r.categories?.join(', '),documents_needed:r.documents_needed?.join(', '),coverage_zip_codes:r.coverage_zip_codes?.join(', ')});host.scrollIntoView({behavior:'smooth',block:'start'});host.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const editing=f.get('editing');const record={...r};for(const [k,v] of f.entries())if(k!=='editing')record[k]=v;for(const k of ['categories','documents_needed','coverage_zip_codes'])record[k]=String(record[k]||'').split(',').map(x=>x.trim()).filter(Boolean);record.is_active=f.has('is_active');record.priority_weight=Number(record.priority_weight)||0;try{await adminFetch(editing?`/api/admin/resources/${editing}`:'/api/admin/resources',{method:editing?'PUT':'POST',body:JSON.stringify(record)});toast(t('updated'));await loadAdmin()}catch(err){toast(err.message)}})}
async function renderRoute(){document.title=`BenefitBridge — ${location.pathname==='/about'?t('about'):location.pathname==='/privacy'?t('privacy'):location.pathname==='/admin'?t('dashboard'):t('hero')}`;const path=location.pathname;if(path==='/'){renderHome();return}if(path==='/questions'){renderWizard();return}if(path==='/about'||path==='/privacy'){renderPlain(path.slice(1));return}if(path==='/admin'){if(state.adminToken&&!state.analytics)await loadAdmin();else renderAdmin();return}const m=path.match(/^\/plan\/([A-Za-z0-9_-]{32,})(\/resources)?$/);if(m){if(state.plan?.id!==m[1]){main.innerHTML=`<div class="shell loading" role="status">${t('loading')}</div>`;try{state.plan=await api(`/api/plans/${m[1]}?lang=${lang}`);state.crisis=!!state.plan.profile.crisis_flag}catch(e){main.innerHTML=`<div class="shell empty"><h1>${esc(e.message)}</h1><a href="/" data-link>${t('startOver')}</a></div>`;return}}if(m[2])renderResults();else renderActionPlan();return}renderHome()}
setLanguage(lang);
